<?php
/**
 * Logo block: the wordmark from assets/logo.svg (generated by brand/build.py), linking home.
 * Its colors come from CSS: the text color for "Miguel", the accent color for "Rojas".
 *
 * @package photos
 */

$photos_logo = file_get_contents( get_theme_file_path( 'assets/logo.svg' ) ); // phpcs:ignore WordPress.WP.AlternativeFunctions
if ( ! $photos_logo ) {
	return;
}
?>
<a href="<?php echo esc_url( home_url( '/' ) ); ?>" rel="home" <?php echo get_block_wrapper_attributes( array( 'class' => 'photos-logo', 'aria-label' => get_bloginfo( 'name' ) ) ); ?>><?php echo $photos_logo; // phpcs:ignore WordPress.Security.EscapeOutput -- theme file, not user input. ?></a>
